// Deja el nombre como lo entiende Tinkazo: sin caracteres invisibles,
// sin comas, con un solo espacio entre palabras y 40 letras como mucho.
function limpiar(texto) {
  return String(texto || '')
    .replace(/[​-‏⁠﻿]/g, '')
    .replace(/,/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 40)
}
return { json: { nombre: limpiar($json.nombre) } }

