// Arma la lista para Tinkazo: un nombre por línea, sin repetidos
// (aunque cambien mayúsculas o tildes), sin enlaces ni correos.
function limpiar(texto) {
  return String(texto || '')
    .replace(/[​-‏⁠﻿]/g, '')
    .replace(/,/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 40)
}

function clave(texto) {
  return texto.normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
}

const vistos = {}
const nombres = []

for (const item of $input.all()) {
  const nombre = limpiar(item.json.nombre)
  if (nombre.length < 2) continue
  if (/https?:|www\.|@/i.test(nombre)) continue
  const k = clave(nombre)
  if (vistos[k]) continue
  vistos[k] = true
  nombres.push(nombre)
}

return [{ json: { cantidad: nombres.length, lista: nombres.join('\n') } }]
